/* Pure demo rules, shared by the UI and smoke checks. No health inference. */
(function(root){
  const split = text => String(text||'').split(/[，,、;；\n]+/).map(x=>x.trim()).filter(Boolean);
  const normalize = text => {const clean=String(text||'').trim();return (root.INGREDIENT_ALIASES||{})[clean]||clean;};
  const defaultPortion = name => ({鸡蛋:[1,'个'],西红柿:[1,'个'],鸡肉:[120,'g'],猪肉:[100,'g'],牛肉:[120,'g'],虾:[100,'g'],鱼:[200,'g'],土豆:[100,'g'],豆腐:[100,'g'],菠菜:[100,'g'],香菇:[60,'g'],蘑菇:[60,'g'],黄瓜:[100,'g'],包菜:[100,'g'],西兰花:[100,'g'],胡萝卜:[80,'g'],青椒:[80,'g'],花生:[20,'g'],洋葱:[60,'g'],米饭:[150,'g'],意面:[80,'g'],椰奶:[80,'ml']})[name]||[100,'g'];
  function amount(text){const m=String(text||'').trim().match(/^(\d+(?:\.\d+)?)\s*(g|克|kg|千克|公斤|斤|个|ml|毫升)$/i);if(!m)return null;let value=Number(m[1]),unit=m[2].toLowerCase();if(['kg','千克','公斤'].includes(unit)){value*=1000;unit='g';}if(unit==='斤'){value*=500;unit='g';}if(unit==='克')unit='g';if(unit==='毫升')unit='ml';return {value,unit};}
  function restrictions(config){return [...split(config.allergies),...(config.includeOthers?split(config.others):[])].map(normalize);}
  function isRestricted(recipe,config){const terms=restrictions(config);if(terms.length&&recipe.uncertain)return true;const parts=[...recipe.ingredients,...recipe.seasonings];const groups={海鲜:['鱼','虾'],坚果:['花生'],大豆:['豆腐','生抽','豆瓣酱'],豆类:['豆腐','生抽','豆瓣酱'],小麦:['意面','生抽','豆瓣酱'],麸质:['意面','生抽','豆瓣酱'],蛋:['鸡蛋'],辣:['辣椒','豆瓣酱','咖喱酱','韩式辣酱']};return terms.some(term=>{let targets=[term];for(const [key,values]of Object.entries(groups))if(term.includes(key))targets.push(...values);return parts.some(p=>targets.some(t=>t&&((p.includes(t))||t.includes(p))));});}
  function missing(recipe,config){const names=new Set(config.ingredients.map(x=>normalize(x.name)));const main=recipe.ingredients.filter(x=>!names.has(x));const spices=config.seasoningMode==='check'?recipe.seasonings.filter(x=>!config.seasonings.includes(x)):[];return {main,spices,all:[...main,...spices]};}
  function eligible(recipes,config){return recipes.filter(r=>!isRestricted(r,config)).filter(r=>!config.flavor||config.flavor==='不限'||r.flavors.includes(config.flavor)).filter(r=>config.allowBuy||missing(r,config).all.length===0).filter(r=>fitsQuantities(r,[],config)).filter(r=>!config.health||r.healthFixture!==3).sort((a,b)=>Number(a.special)-Number(b.special)||(config.goal==='偏少油'?a.fat-b.fat:config.goal==='偏清淡'?Number(b.flavors.includes('清淡'))-Number(a.flavors.includes('清淡')):0));}
  function fitsQuantities(recipe,selected,config){if(config.allowBuy)return true;const needs={};for(const r of [...selected,recipe])for(const n of r.ingredients){const [qty,unit]=defaultPortion(n);needs[n]??={value:0,unit};needs[n].value+=qty*config.servings;}return Object.entries(needs).every(([name,need])=>{const stock=config.ingredients.find(x=>normalize(x.name)===name);const available=amount(stock?.amount);return !available||available.unit!==need.unit||available.value>=need.value;});}
  function buildMeal(recipes,config,iteration=0,counts=null){const pool=eligible(recipes,config);const meat=pool.some(r=>r.type==='meat');const targets=counts?[counts]:meat?[{meat:1,veg:2,soup:0},{meat:2,veg:1,soup:0},{meat:1,veg:1,soup:1}]:[{meat:0,veg:3,soup:0},{meat:0,veg:2,soup:1}];function pick(target){const selected=[];for(const type of ['meat','veg','soup']){let options=pool.filter(r=>r.type===type);const common=options.filter(r=>!r.special),special=options.filter(r=>r.special);const rotate=arr=>arr.length?[...arr.slice(iteration%arr.length),...arr.slice(0,iteration%arr.length)]:[];options=[...rotate(common),...rotate(special)];for(let i=0;i<(target[type]||0);i++){const choices=options.filter(r=>!selected.some(s=>s.id===r.id)&&fitsQuantities(r,selected,config));if(!choices.length)break;const distinct=choices.find(r=>!selected.some(s=>s.ingredients.length===r.ingredients.length&&s.ingredients.every(n=>r.ingredients.includes(n))))||choices[0];selected.push(distinct);}}return {selected,target,total:target.meat+target.veg+target.soup,pool};}const combinations=targets.map(pick);const complete=combinations.filter(c=>c.selected.length===c.total);if(complete.length)return complete[iteration%complete.length];const best=Math.max(...combinations.map(c=>c.selected.length));const partial=combinations.filter(c=>c.selected.length===best);return partial[iteration%partial.length];}
  function parseIngredients(text){return split(text).map(part=>{const m=part.match(/^(.+?)(\d.*|[一二两三四五六七八九十半]+[个把根块斤袋].*)?$/);if(!m)return null;return {name:normalize(m[1].trim()),amount:(m[2]||'').trim()};}).filter(x=>x&&x.name);}
  const api={split,normalize,defaultPortion,amount,restrictions,isRestricted,missing,eligible,fitsQuantities,buildMeal,parseIngredients};root.ShiweiEngine=api;
  if(typeof module!=='undefined'&&module.exports)module.exports=api;
})(typeof window==='undefined'?globalThis:window);
